  "c085": {"q":"解析說「覓」裡的「見」代表什麼？","o":["用眼睛搜尋","看見蜜蜂","山中景色","把東西藏起來"],"a":0},
  "c086": {"q":"依解析，「至」的字形像什麼？","o":["手持棍棒","箭射到地面（本義是到達）","絲線細密","人走到路口"],"a":1},
  "c087": {"q":"照解析，什麼時候才用有糸旁的「緻」？","o":["表示到達時","表示招來時","只有形容「細密精美」時（精緻、細緻）","所有「致」都可以換成「緻」"],"a":2},
  "c088": {"q":"依解析，「制」和「製」怎麼分？","o":["「制」是動手做東西","「製」是抽象法度","兩字完全相同","抽象的法度管束用「制」；動手做東西用「製」（有衣）"],"a":3},
  "c089": {"q":"解析說「製」的本義是什麼？","o":["裁製衣服（引申為做出各種物品）","用網子捕獵","裁斷木頭","整治水患"],"a":0},
  "c090": {"q":"依解析，「治」為什麼是水字旁？","o":["因為治病要喝水","因為本義是整治水患（大禹治水）","因為「台」表示水","因為水最難管理"],"a":1},
  "c091": {"q":"解析說「置」的本義是什麼？","o":["聰明才識","裁斷布料","釋放（把網打直放走獵物），引申為安放","用火提煉"],"a":2},
  "c092": {"q":"依解析，「討」為什麼是言字旁？","o":["因為討論很吵","因為「寸」表示嘴巴","因為要用手比劃","因為本義是用言語聲罪征伐、追究"],"a":3},
  "c093": {"q":"解析說「銷售」為什麼用金字旁的「銷」？","o":["本義是熔化金屬，引申為貨物「化」為錢賣出去","因為賣東西要收金子","因為「肖」表示金屬","因為水會把貨沖走"],"a":0},
